    with open(file_path, 'r') as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            try:
                tx_id = row['tx_id']
                timestamp = datetime.fromisoformat(row['timestamp']).astimezone(timezone.utc)
                amount = Decimal(row['amount'])
                status = row['status']
            except (KeyError, ValueError, TypeError) as e:
                print(f"Error processing row: {row}\n{e}", file=sys.stderr)
                continue

            if tx_id in transactions:
                if timestamp > transactions[tx_id]['timestamp']:
                    transactions[tx_id] = {'timestamp': timestamp, 'amount': amount, 'status': status}
            else:
                transactions[tx_id] = {'timestamp': timestamp, 'amount': amount, 'status': status}

    total_valid_amount = Decimal('0.00')
    valid_count = 0
    failed_count = 0

    for tx_id, tx in transactions.items():
        if tx['status'] == 'SUCCESS':
            total_valid_amount += tx['amount']
            valid_count += 1
        elif tx['status'] == 'FAILED':
            failed_count += 1

    result = {
        'total_valid_amount': str(total_valid_amount.quantize(Decimal('0.00'))),
        'valid_count': valid_count,
        'failed_count': failed_count
    }

    print(json.dumps(result))

if __name__ == '__main__':
    import sys
    if len(sys.argv) != 2:
        print("Usage: python reconcile.py <csv_file>", file=sys.stderr)
        sys.exit(1)

